WITH valid_transactions AS (SELECT *, CASE WHEN txn_type IN ('DEBIT', 'REFUND') THEN 'Group A' ELSE 'Other' END AS txn_type_group FROM transactions WHERE amount < 3300), agg AS (SELECT txn_type, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(merchant))) AS merchant_values, COUNT(CASE WHEN merchant = 'Amazon' THEN 1 END) AS amazon_count FROM valid_transactions GROUP BY txn_type) SELECT txn_type, merchant_values, amazon_count FROM agg ORDER BY amazon_count DESC;
